import type { RegistryEntry } from "./rules/registry";
import type { SpecNodeRules } from "./specRules/nodeRulesFromSpec";

const GENERATED_HEADER = `// Generated by @autumn/atmn-generator from packages/openapi/openapi-internal.yml.
// Do not edit — run \`bun generate\` in packages/atmn-generator instead.
`;

/** A `nonEmpty` rule owns the wording for its field, so the spec's bare `minItems` steps aside. */
const withoutOwnedMinItems = ({
	fields,
	rules,
}: {
	fields: SpecNodeRules["fields"];
	rules: RegistryEntry["rules"];
}): SpecNodeRules["fields"] => {
	if (!fields) return fields;
	const owned = new Set(
		(rules ?? [])
			.filter((rule) => rule.kind === "nonEmpty")
			.map((rule) => rule.field),
	);
	if (owned.size === 0) return fields;
	return Object.fromEntries(
		Object.entries(fields).flatMap(([field, constraints]) => {
			if (!owned.has(field)) return [[field, constraints]];
			const { minItems: _minItems, ...rest } = constraints;
			return Object.keys(rest).length > 0 ? [[field, rest]] : [];
		}),
	);
};

/** The data half of the lint: spec rules and registry entries, merged per path. */
export const emitLintRulesModule = ({
	specRules,
	registry,
}: {
	specRules: Record<string, SpecNodeRules>;
	registry: Record<string, RegistryEntry>;
}): string => {
	const paths = [
		...new Set([...Object.keys(specRules), ...Object.keys(registry)]),
	].sort();

	const merged = Object.fromEntries(
		paths.map((path) => {
			const entry = registry[path];
			const spec = specRules[path];
			const required = [
				...new Set([...(spec?.required ?? []), ...(entry?.required ?? [])]),
			].sort();
			return [
				path,
				{
					label: entry?.label,
					idField: entry?.idField,
					required: required.length > 0 ? required : undefined,
					hidden: spec?.hidden,
					fields: withoutOwnedMinItems({
						fields: spec?.fields,
						rules: entry?.rules,
					}),
					keys: spec?.keys,
					variants: spec?.variants,
					rules: entry?.rules,
				},
			];
		}),
	);

	return [
		GENERATED_HEADER,
		`import type { LintRules } from "./lintRuntime.js";`,
		`export const LINT_RULES: LintRules = ${JSON.stringify(merged, null, "\t")};\n`,
	].join("\n");
};
